//! Native engine benchmark. Loads a corpus generated by
//! `differential/gen_corpus.mjs`, then times index build, the packed search
//! path (the engine side of `searchJoined`) under app-like option combos,
//! auto-suggest, and snapshot save/load. Run with `--release`.
//!
//! Usage: cargo run --release --example bench_search <corpus.json> [rounds]

use minisearch_wasm::{
    AutoSuggestOptions, CombineWith, FuzzySetting, MiniSearch, MiniSearchOptions, SearchOptions,
    TokenizerMode,
};
use serde_json::Value;
use std::time::Instant;

fn median(mut samples: Vec<f64>) -> f64 {
    samples.sort_by(|a, b| a.partial_cmp(b).unwrap());
    samples[samples.len() / 2]
}

fn bench<F: FnMut() -> u64>(name: &str, rounds: usize, mut run: F) {
    // one warmup
    let mut checksum = run();
    let mut samples = Vec::with_capacity(rounds);
    for _ in 0..rounds {
        let start = Instant::now();
        checksum = checksum.wrapping_add(run());
        samples.push(start.elapsed().as_secs_f64() * 1000.0);
    }
    println!(
        "{name:<34} median {:>9.3} ms   (checksum {checksum})",
        median(samples)
    );
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let corpus: Value = serde_json::from_str(&std::fs::read_to_string(&args[1]).unwrap()).unwrap();
    let rounds: usize = args.get(2).map(|r| r.parse().unwrap()).unwrap_or(9);
    let docs: Vec<Value> = corpus["docs"].as_array().unwrap().clone();
    let queries: Vec<String> = corpus["queries"]
        .as_array()
        .unwrap()
        .iter()
        .map(|q| q.as_str().unwrap().to_owned())
        .collect();
    let docs_json = serde_json::to_string(&docs).unwrap();

    let options = || MiniSearchOptions {
        fields: vec!["title".to_owned(), "text".to_owned()],
        id_field: "id".to_owned(),
        store_fields: vec![],
        tokenizer: TokenizerMode::Default,
        search_options: SearchOptions {
            prefix: true,
            fuzzy: Some(FuzzySetting::Distance(0.2)),
            combine_with: CombineWith::And,
            ..SearchOptions::default()
        },
        auto_suggest_options: None,
    };

    println!(
        "corpus: {} docs, {} queries, rounds={rounds}",
        docs.len(),
        queries.len()
    );

    bench("addAll (build index)", rounds, || {
        let mut search = MiniSearch::new(options());
        let parsed: Vec<Value> = serde_json::from_str(&docs_json).unwrap();
        search.add_all(parsed).unwrap();
        search.term_count() as u64
    });

    let mut search = MiniSearch::new(options());
    search.add_all(docs.clone()).unwrap();

    bench("searchJoined AND prefix+fuzzy", rounds, || {
        let mut hits = 0u64;
        for query in &queries {
            hits += search.search_packed_default(query, false).ids.len() as u64;
        }
        hits
    });

    bench("searchJoined OR prefix+fuzzy", rounds, || {
        let mut hits = 0u64;
        for query in &queries {
            hits += search.search_packed_default(query, true).ids.len() as u64;
        }
        hits
    });

    bench("search_packed plain OR", rounds, || {
        let mut hits = 0u64;
        for query in &queries {
            hits += search
                .search_packed(query, SearchOptions::default())
                .ids
                .len() as u64;
        }
        hits
    });

    bench("autoSuggest default", rounds, || {
        let mut suggestions = 0u64;
        for query in &queries {
            suggestions += search.auto_suggest(query, None).len() as u64;
        }
        suggestions
    });

    bench("autoSuggest fuzzy", rounds, || {
        let per_call = AutoSuggestOptions {
            fuzzy: Some(FuzzySetting::Distance(0.2)),
            ..AutoSuggestOptions::default()
        };
        let mut suggestions = 0u64;
        for query in &queries {
            suggestions += search.auto_suggest(query, Some(&per_call)).len() as u64;
        }
        suggestions
    });

    bench("search full (compat path)", rounds, || {
        let mut hits = 0u64;
        for query in &queries {
            let opts = SearchOptions {
                prefix: true,
                fuzzy: Some(FuzzySetting::Distance(0.2)),
                combine_with: CombineWith::And,
                ..SearchOptions::default()
            };
            hits += search.search(query, opts).len() as u64;
        }
        hits
    });

    let bytes = search.to_bytes().unwrap();
    println!("snapshot size: {} bytes", bytes.len());
    bench("toBytes", rounds, || {
        search.to_bytes().unwrap().len() as u64
    });
    bench("fromBytes", rounds, || {
        MiniSearch::from_bytes(&bytes).unwrap().term_count() as u64
    });
}
